def iterative_factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for value in range(2, n + 1):
        result *= value
    return result

def mean_valid_mark(marks):
    valid_marks = []
    for mark in marks:
        if 0 <= mark <= 100:
            valid_marks.append(mark)

    if len(valid_marks) == 0:
        return None
    return sum(valid_marks) / len(valid_marks)

